    Deref,
    DerefMut,
};
use ::sys::error::Error;

//==================================================================================================
// Kernel Frame
//==================================================================================================

/// A type that represents a kernel frame.
#[derive(Debug)]
#[verus_verify(external_derive)]
pub struct KernelFrame {
    /// Frame address.
    base: FrameAddress,
}

